"""Download and validate both frozen external P300 datasets."""
from __future__ import annotations

import shutil
import subprocess
import sys
from pathlib import Path

INPUT = Path("/kaggle/input")
WORK = Path("/kaggle/working")


def find_code() -> Path:
    for path in INPUT.rglob("scripts/prepare_bnci.py"):
        return path.parents[1]
    raise FileNotFoundError("P3A code dataset is not attached")


# Exact source snapshots avoid stale attached dataset versions.
import base64
LOADER = ''
TESTS = ''

code = WORK / "code"
shutil.copytree(find_code(), code, dirs_exist_ok=True)
(code / "src/p3a/data/loaders/bnci2015_003.py").write_bytes(base64.b64decode(LOADER))
(code / "tests/test_bnci_loaders.py").write_bytes(base64.b64decode(TESTS))
subprocess.run([sys.executable, "-m", "pip", "install", "-e", str(code), "pytest"], check=True)
subprocess.run([sys.executable, "-m", "pytest", "-q", "tests/test_bnci_loaders.py", "tests/test_bnci_splits.py"], cwd=code, check=True)
subprocess.run([
    sys.executable, str(code / "scripts" / "prepare_bnci.py"),
    "--data-root", "/kaggle/temp/p3a_bnci",
    "--out-dir", str(WORK / "out"), "--seed", "20260929",
], check=True)
